import React, { useEffect, useState } from 'react';
import panda1 from './panda.png';
import panda2 from './pandaa.png';
import './App.css';

function FloatingPandas() {
  const [pandas, setPandas] = useState([
    { src: panda1, x: 50, y: 50, dx: 1, dy: 1 },
    { src: panda2, x: 300, y: 200, dx: 1.2, dy: 0.8 },
    { src: panda1, x: 500, y: 150, dx: 0.9, dy: 1.1 },
  ]);

  useEffect(() => {
    const chartTop = 150, chartBottom = 900, chartLeft = 100, chartRight = 950;

    const interval = setInterval(() => {
      setPandas(prev =>
        prev.map(p => {
          let newX = p.x + p.dx;
          let newY = p.y + p.dy;

          if (newX >= chartRight || newX <= chartLeft) p.dx = -p.dx;
          if (newY >= chartBottom || newY <= chartTop) p.dy = -p.dy;

          return { ...p, x: newX, y: newY, dx: p.dx, dy: p.dy };
        })
      );
    }, 30);

    return () => clearInterval(interval);
  }, []);

  return (
    <>
      {pandas.map((p, i) => (
        <img
          key={i}
          src={p.src}
          alt={`panda${i}`}
          className="panda"
          style={{ left: p.x, top: p.y, position: 'fixed', width: 60, height: 60, pointerEvents: 'none' }}
        />
      ))}
    </>
  );
}

export default FloatingPandas;
